	// b-2 changes the content of e-1: conflict, whole batch rejected.
	conflictBody := `{
		"batchId": "b-2",
		"samples": [
			{"eventId": "e-1", "observedAt": "2026-09-30T08:15:00Z", "values": {"temperature": 99.9}},
