	}
	page := fetchHistory(t, h, "dev-1", "")
	if len(page.Samples) != 20 {
		t.Fatalf("default page size = %d, want 20", len(page.Samples))
	}
	if page.NextCursor == nil {
		t.Fatal("expected a cursor after 20 samples")
	}
}

