package fleet

import (
	"errors"
	"sort"
	"sync"
	"time"
)

var (
	ErrDeviceNotFound = errors.New("device not found")
	ErrConflict       = errors.New("conflicting event or batch content")
)

type Device struct {
	ID            string             `json:"id"`
	Site          string             `json:"site"`
	RegisteredAt  time.Time          `json:"registeredAt"`
	LastSeenAt    time.Time          `json:"lastSeenAt"`
	LastTelemetry map[string]float64 `json:"lastTelemetry,omitempty"`

	history []HistoryEntry
	events  map[string]int64
	batches map[string]BatchRecord
}

// HistoryEntry is one receive-ordered record in a device's telemetry history.
type HistoryEntry struct {
	Seq        int64              `json:"seq"`
	EventID    string             `json:"eventId,omitempty"`
	ObservedAt time.Time          `json:"observedAt"`
	ReceivedAt time.Time          `json:"receivedAt"`
	Values     map[string]float64 `json:"values"`
	BatchID    string             `json:"batchId,omitempty"`
}

// ReplaySample is a validated sample submitted through a replay batch.
type ReplaySample struct {
	EventID    string
	ObservedAt time.Time
	Values     map[string]float64
}

// SampleResult describes how a single sample was accepted.
type SampleResult struct {
	EventID string `json:"eventId"`
	Seq     int64  `json:"seq"`
	Status  string `json:"status"`
}

// ReplayReceipt is returned for both new (202) and idempotent (200) batches.
type ReplayReceipt struct {
	BatchID        string         `json:"batchId"`
	Results        []SampleResult `json:"results"`
	NewCount       int            `json:"newCount"`
	DuplicateCount int            `json:"duplicateCount"`
}

// BatchRecord stores the ordered content and first receipt of a batch.
type BatchRecord struct {
	Samples []ReplaySample
	Receipt ReplayReceipt
}

type Store struct {
	mu      sync.RWMutex
	devices map[string]Device
	now     func() time.Time
}

func NewStore() *Store {
	return &Store{devices: make(map[string]Device), now: time.Now}
}

func (s *Store) Register(id, site string) (Device, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if current, ok := s.devices[id]; ok {
		return cloneDevice(current), false
	}
	now := s.now().UTC()
	device := Device{
		ID:           id,
		Site:         site,
		RegisteredAt: now,
		LastSeenAt:   now,
		events:       make(map[string]int64),
		batches:      make(map[string]BatchRecord),
	}
	s.devices[id] = device
	return cloneDevice(device), true
}

// RecordTelemetry appends a direct telemetry write to the device's history.
// The sampling time is the receive time.
func (s *Store) RecordTelemetry(id string, values map[string]float64) (HistoryEntry, Device, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	device, ok := s.devices[id]
	if !ok {
		return HistoryEntry{}, Device{}, ErrDeviceNotFound
	}
	now := s.now().UTC()
	seq := int64(len(device.history)) + 1
	entry := HistoryEntry{
		Seq:        seq,
		ObservedAt: now,
		ReceivedAt: now,
		Values:     cloneTelemetry(values),
	}
	device.history = append(device.history, entry)
	device.LastSeenAt = now
	device.LastTelemetry = cloneTelemetry(values)
	s.devices[id] = device
	return cloneHistoryEntry(entry), cloneDevice(device), nil
}

// ReplayBatch atomically applies a validated batch.
//
// New batches are assigned sequence numbers per device starting at 1 with no
// gaps. A sample whose eventId already exists with identical content (same
// observed instant, same values key-by-key) is a duplicate and reuses the
// original sequence number. Any content conflict, or a batchId reused with
// different ordered content, fails with ErrConflict and leaves no state
// change. A batchId resubmitted with identical content returns the stored
// receipt with idempotent=true.
func (s *Store) ReplayBatch(id, batchID string, samples []ReplaySample) (receipt ReplayReceipt, idempotent bool, err error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	device, ok := s.devices[id]
	if !ok {
		return ReplayReceipt{}, false, ErrDeviceNotFound
	}
	if existing, ok := device.batches[batchID]; ok {
		if sameBatchSamples(existing.Samples, samples) {
			return cloneReceipt(existing.Receipt), true, nil
		}
		return ReplayReceipt{}, false, ErrConflict
	}

	now := s.now().UTC()
	receipt = ReplayReceipt{BatchID: batchID, Results: make([]SampleResult, 0, len(samples))}
	var added []HistoryEntry
	var lastNewValues map[string]float64
	newCount, dupCount := 0, 0

	for _, sample := range samples {
		if seq, known := device.events[sample.EventID]; known {
			entry := device.history[seq-1]
			if entry.ObservedAt.Equal(sample.ObservedAt) && sameValues(entry.Values, sample.Values) {
				receipt.Results = append(receipt.Results, SampleResult{
					EventID: sample.EventID,
					Seq:     seq,
					Status:  "duplicate",
				})
				dupCount++
				continue
			}
			return ReplayReceipt{}, false, ErrConflict
		}
		seq := int64(len(device.history)) + int64(len(added)) + 1
		entry := HistoryEntry{
			Seq:        seq,
			EventID:    sample.EventID,
			ObservedAt: sample.ObservedAt,
			ReceivedAt: now,
			Values:     cloneTelemetry(sample.Values),
			BatchID:    batchID,
		}
		added = append(added, entry)
		receipt.Results = append(receipt.Results, SampleResult{
			EventID: sample.EventID,
			Seq:     seq,
			Status:  "new",
		})
		newCount++
		lastNewValues = cloneTelemetry(sample.Values)
	}

	device.history = append(device.history, added...)
	for _, entry := range added {
		device.events[entry.EventID] = entry.Seq
	}
	if newCount > 0 {
		device.LastSeenAt = now
		device.LastTelemetry = lastNewValues
	}
	device.batches[batchID] = BatchRecord{
		Samples: cloneBatchSamples(samples),
		Receipt: cloneReceipt(receipt),
	}
	s.devices[id] = device
	return receipt, false, nil
}

// MaxSeq returns the current largest receive sequence number for a device.
func (s *Store) MaxSeq(id string) (int64, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	device, ok := s.devices[id]
	if !ok {
		return 0, false
	}
	return int64(len(device.history)), true
}

// QueryHistory returns entries with sequence numbers in (after, upper] whose
// sampling time falls in [from, to] (both bounds inclusive). At most limit
// entries are returned; callers request limit+1 to detect a next page.
func (s *Store) QueryHistory(id string, from, to *time.Time, upper, after int64, limit int) ([]HistoryEntry, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	device, ok := s.devices[id]
	if !ok {
		return nil, ErrDeviceNotFound
	}
	result := make([]HistoryEntry, 0, min(limit, len(device.history)))
	for _, entry := range device.history {
		if entry.Seq <= after {
			continue
		}
		if entry.Seq > upper {
			break
		}
		if from != nil && entry.ObservedAt.Before(*from) {
			continue
		}
		if to != nil && entry.ObservedAt.After(*to) {
			continue
		}
		result = append(result, cloneHistoryEntry(entry))
		if len(result) >= limit {
			break
		}
	}
	return result, nil
}

func (s *Store) Snapshot() []Device {
	s.mu.RLock()
	defer s.mu.RUnlock()
	result := make([]Device, 0, len(s.devices))
	for _, device := range s.devices {
		result = append(result, cloneDevice(device))
	}
	sort.Slice(result, func(i, j int) bool { return result[i].ID < result[j].ID })
	return result
}

func sameValues(a, b map[string]float64) bool {
	if len(a) != len(b) {
		return false
	}
	for key, value := range a {
		other, ok := b[key]
		if !ok || value != other {
			return false
		}
	}
	return true
}

func sameBatchSamples(a, b []ReplaySample) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i].EventID != b[i].EventID ||
			!a[i].ObservedAt.Equal(b[i].ObservedAt) ||
			!sameValues(a[i].Values, b[i].Values) {
			return false
		}
	}
	return true
}

func cloneDevice(device Device) Device {
	device.LastTelemetry = cloneTelemetry(device.LastTelemetry)
	return device
}

func cloneTelemetry(values map[string]float64) map[string]float64 {
	if values == nil {
		return nil
	}
	cloned := make(map[string]float64, len(values))
	for key, value := range values {
		cloned[key] = value
	}
	return cloned
}

func cloneHistoryEntry(entry HistoryEntry) HistoryEntry {
	entry.Values = cloneTelemetry(entry.Values)
	return entry
}

func cloneBatchSamples(samples []ReplaySample) []ReplaySample {
	cloned := make([]ReplaySample, len(samples))
	for i, sample := range samples {
		cloned[i] = ReplaySample{
			EventID:    sample.EventID,
			ObservedAt: sample.ObservedAt,
			Values:     cloneTelemetry(sample.Values),
		}
	}
	return cloned
}

func cloneReceipt(receipt ReplayReceipt) ReplayReceipt {
	cloned := receipt
	cloned.Results = append([]SampleResult(nil), receipt.Results...)
	return cloned
}

package fleet

import (
	"errors"
	"sort"
	"sync"
	"time"
)

var (
	ErrDeviceNotFound = errors.New("device not found")
	ErrConflict       = errors.New("conflicting event or batch content")
)

type Device struct {
	ID            string             `json:"id"`
	Site          string             `json:"site"`
	RegisteredAt  time.Time          `json:"registeredAt"`
	LastSeenAt    time.Time          `json:"lastSeenAt"`
	LastTelemetry map[string]float64 `json:"lastTelemetry,omitempty"`

	history []HistoryEntry
	events  map[string]int64
	batches map[string]BatchRecord
}

// HistoryEntry is one receive-ordered record in a device's telemetry history.
type HistoryEntry struct {
	Seq        int64              `json:"seq"`
	EventID    string             `json:"eventId,omitempty"`
	ObservedAt time.Time          `json:"observedAt"`
	ReceivedAt time.Time          `json:"receivedAt"`
	Values     map[string]float64 `json:"values"`
	BatchID    string             `json:"batchId,omitempty"`
}

// ReplaySample is a validated sample submitted through a replay batch.
type ReplaySample struct {
	EventID    string
	ObservedAt time.Time
	Values     map[string]float64
}

// SampleResult describes how a single sample was accepted.
type SampleResult struct {
	EventID string `json:"eventId"`
	Seq     int64  `json:"seq"`
	Status  string `json:"status"`
}

// ReplayReceipt is returned for both new (202) and idempotent (200) batches.
type ReplayReceipt struct {
	BatchID        string         `json:"batchId"`
	Results        []SampleResult `json:"results"`
	NewCount       int            `json:"newCount"`
	DuplicateCount int            `json:"duplicateCount"`
}

// BatchRecord stores the ordered content and first receipt of a batch.
type BatchRecord struct {
	Samples []ReplaySample
	Receipt ReplayReceipt
}

type Store struct {
	mu      sync.RWMutex
	devices map[string]Device
	now     func() time.Time
}

func NewStore() *Store {
	return &Store{devices: make(map[string]Device), now: time.Now}
}

func (s *Store) Register(id, site string) (Device, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if current, ok := s.devices[id]; ok {
		return cloneDevice(current), false
	}
	now := s.now().UTC()
	device := Device{
		ID:           id,
		Site:         site,
		RegisteredAt: now,
		LastSeenAt:   now,
		events:       make(map[string]int64),
		batches:      make(map[string]BatchRecord),
	}
	s.devices[id] = device
	return cloneDevice(device), true
}

// RecordTelemetry appends a direct telemetry write to the device's history.
// The sampling time is the receive time.
func (s *Store) RecordTelemetry(id string, values map[string]float64) (HistoryEntry, Device, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	device, ok := s.devices[id]
	if !ok {
		return HistoryEntry{}, Device{}, ErrDeviceNotFound
	}
	now := s.now().UTC()
	seq := int64(len(device.history)) + 1
	entry := HistoryEntry{
		Seq:        seq,
		ObservedAt: now,
		ReceivedAt: now,
		Values:     cloneTelemetry(values),
	}
	device.history = append(device.history, entry)
	device.LastSeenAt = now
	device.LastTelemetry = cloneTelemetry(values)
	s.devices[id] = device
	return cloneHistoryEntry(entry), cloneDevice(device), nil
}

// ReplayBatch atomically applies a validated batch.
//
// New batches are assigned sequence numbers per device starting at 1 with no
// gaps. A sample whose eventId already exists with identical content (same
// observed instant, same values key-by-key) is a duplicate and reuses the
// original sequence number. Any content conflict, or a batchId reused with
// different ordered content, fails with ErrConflict and leaves no state
// change. A batchId resubmitted with identical content returns the stored
// receipt with idempotent=true.
func (s *Store) ReplayBatch(id, batchID string, samples []ReplaySample) (receipt ReplayReceipt, idempotent bool, err error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	device, ok := s.devices[id]
	if !ok {
		return ReplayReceipt{}, false, ErrDeviceNotFound
	}
	if existing, ok := device.batches[batchID]; ok {
		if sameBatchSamples(existing.Samples, samples) {
			return cloneReceipt(existing.Receipt), true, nil
		}
		return ReplayReceipt{}, false, ErrConflict
	}

	now := s.now().UTC()
	receipt = ReplayReceipt{BatchID: batchID, Results: make([]SampleResult, 0, len(samples))}
	var added []HistoryEntry
	var lastNewValues map[string]float64
	newCount, dupCount := 0, 0

	for _, sample := range samples {
		if seq, known := device.events[sample.EventID]; known {
			entry := device.history[seq-1]
			if entry.ObservedAt.Equal(sample.ObservedAt) && sameValues(entry.Values, sample.Values) {
				receipt.Results = append(receipt.Results, SampleResult{
					EventID: sample.EventID,
					Seq:     seq,
					Status:  "duplicate",
				})
				dupCount++
				continue
			}
			return ReplayReceipt{}, false, ErrConflict
		}
		seq := int64(len(device.history)) + int64(len(added)) + 1
		entry := HistoryEntry{
			Seq:        seq,
			EventID:    sample.EventID,
			ObservedAt: sample.ObservedAt,
			ReceivedAt: now,
			Values:     cloneTelemetry(sample.Values),
			BatchID:    batchID,
		}
		added = append(added, entry)
		receipt.Results = append(receipt.Results, SampleResult{
			EventID: sample.EventID,
			Seq:     seq,
			Status:  "new",
		})
		newCount++
		lastNewValues = cloneTelemetry(sample.Values)
	}

	device.history = append(device.history, added...)
	for _, entry := range added {
		device.events[entry.EventID] = entry.Seq
	}
	if newCount > 0 {
		device.LastSeenAt = now
		device.LastTelemetry = lastNewValues
	}
	device.batches[batchID] = BatchRecord{
		Samples: cloneBatchSamples(samples),
		Receipt: cloneReceipt(receipt),
	}
	receipt.NewCount = newCount
	receipt.DuplicateCount = dupCount
	s.devices[id] = device
	return receipt, false, nil
}

// MaxSeq returns the current largest receive sequence number for a device.
func (s *Store) MaxSeq(id string) (int64, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	device, ok := s.devices[id]
	if !ok {
		return 0, false
	}
	return int64(len(device.history)), true
}

// QueryHistory returns entries with sequence numbers in (after, upper] whose
// sampling time falls in [from, to] (both bounds inclusive). At most limit
// entries are returned; callers request limit+1 to detect a next page.
func (s *Store) QueryHistory(id string, from, to *time.Time, upper, after int64, limit int) ([]HistoryEntry, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	device, ok := s.devices[id]
	if !ok {
		return nil, ErrDeviceNotFound
	}
	result := make([]HistoryEntry, 0, min(limit, len(device.history)))
	for _, entry := range device.history {
		if entry.Seq <= after {
			continue
		}
		if entry.Seq > upper {
			break
		}
		if from != nil && entry.ObservedAt.Before(*from) {
			continue
		}
		if to != nil && entry.ObservedAt.After(*to) {
			continue
		}
		result = append(result, cloneHistoryEntry(entry))
		if len(result) >= limit {
			break
		}
	}
	return result, nil
}

func (s *Store) Snapshot() []Device {
	s.mu.RLock()
	defer s.mu.RUnlock()
	result := make([]Device, 0, len(s.devices))
	for _, device := range s.devices {
		result = append(result, cloneDevice(device))
	}
	sort.Slice(result, func(i, j int) bool { return result[i].ID < result[j].ID })
	return result
}

func sameValues(a, b map[string]float64) bool {
	if len(a) != len(b) {
		return false
	}
	for key, value := range a {
		other, ok := b[key]
		if !ok || value != other {
			return false
		}
	}
	return true
}

func sameBatchSamples(a, b []ReplaySample) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i].EventID != b[i].EventID ||
			!a[i].ObservedAt.Equal(b[i].ObservedAt) ||
			!sameValues(a[i].Values, b[i].Values) {
			return false
		}
	}
	return true
}

func cloneDevice(device Device) Device {
	device.LastTelemetry = cloneTelemetry(device.LastTelemetry)
	return device
}

func cloneTelemetry(values map[string]float64) map[string]float64 {
	if values == nil {
		return nil
	}
	cloned := make(map[string]float64, len(values))
	for key, value := range values {
		cloned[key] = value
	}
	return cloned
}

func cloneHistoryEntry(entry HistoryEntry) HistoryEntry {
	entry.Values = cloneTelemetry(entry.Values)
	return entry
}

func cloneBatchSamples(samples []ReplaySample) []ReplaySample {
	cloned := make([]ReplaySample, len(samples))
	for i, sample := range samples {
		cloned[i] = ReplaySample{
			EventID:    sample.EventID,
			ObservedAt: sample.ObservedAt,
			Values:     cloneTelemetry(sample.Values),
		}
	}
	return cloned
}

func cloneReceipt(receipt ReplayReceipt) ReplayReceipt {
	cloned := receipt
	cloned.Results = append([]SampleResult(nil), receipt.Results...)
	return cloned
}

package fleet

import (
	"encoding/json"
	"fmt"
	"net/http"
	"testing"
)

type historyPage struct {
	Samples []struct {
		Seq        int64              `json:"seq"`
		ObservedAt string             `json:"observedAt"`
		Values     map[string]float64 `json:"values"`
	} `json:"samples"`
	NextCursor *string `json:"nextCursor"`
}

func fetchHistory(t *testing.T, h http.Handler, id, query string) historyPage {
	t.Helper()
	rec := doJSON(t, h, http.MethodGet, "/v1/devices/"+id+"/history?"+query, "")
	if rec.Code != http.StatusOK {
		t.Fatalf("history status = %d, want %d: %s", rec.Code, http.StatusOK, rec.Body.String())
	}
	var page historyPage
	if err := json.Unmarshal(rec.Body.Bytes(), &page); err != nil {
		t.Fatalf("decode history: %v", err)
	}
	return page
}

func replaySample(t *testing.T, h http.Handler, id, batchID, eventID, observedAt string, values map[string]float64) {
	t.Helper()
	valuesJSON, err := json.Marshal(values)
	if err != nil {
		t.Fatal(err)
	}
	body := fmt.Sprintf(`{
		"batchId": %q,
		"samples": [{"eventId": %q, "observedAt": %q, "values": %s}]
	}`, batchID, eventID, observedAt, string(valuesJSON))
	rec := doJSON(t, h, http.MethodPost, "/v1/devices/"+id+"/replay", body)
	if rec.Code != http.StatusAccepted {
		t.Fatalf("replay %s: %d %s", eventID, rec.Code, rec.Body.String())
	}
}

func TestTelemetryWritesHistory(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")

	rec := doJSON(t, h, http.MethodPost, "/v1/devices/dev-1/telemetry", `{"temperature":21.75}`)
	if rec.Code != http.StatusAccepted {
		t.Fatalf("telemetry: %d %s", rec.Code, rec.Body.String())
	}

	page := fetchHistory(t, h, "dev-1", "")
	if len(page.Samples) != 1 {
		t.Fatalf("history count = %d, want 1", len(page.Samples))
	}
	sample := page.Samples[0]
	if sample.Seq != 1 || sample.Values["temperature"] != 21.75 {
		t.Fatalf("sample = %+v, want seq 1 temperature 21.75", sample)
	}
	if sample.ObservedAt == "" {
		t.Fatal("observedAt is empty")
	}
	if page.NextCursor != nil {
		t.Fatalf("nextCursor = %q, want nil", *page.NextCursor)
	}
}

func TestHistoryFiltersByTimeRange(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	for i, ts := range []string{
		"2026-01-01T00:00:00Z",
		"2026-01-02T00:00:00Z",
		"2026-01-03T00:00:00Z",
	} {
		replaySample(t, h, "dev-1", fmt.Sprintf("b-%d", i), fmt.Sprintf("e-%d", i), ts, map[string]float64{"v": float64(i + 1)})
	}

	// Both boundaries are inclusive.
	page := fetchHistory(t, h, "dev-1", "from=2026-01-01T00:00:00Z&to=2026-01-03T00:00:00Z")
	if len(page.Samples) != 3 {
		t.Fatalf("inclusive range count = %d, want 3", len(page.Samples))
	}
	page = fetchHistory(t, h, "dev-1", "from=2026-01-02T00:00:00Z&to=2026-01-02T00:00:00Z")
	if len(page.Samples) != 1 || page.Samples[0].Values["v"] != 2 {
		t.Fatalf("single-day range = %+v, want v=2", page.Samples)
	}
	page = fetchHistory(t, h, "dev-1", "from=2025-12-31T00:00:00Z&to=2025-12-31T23:59:59Z")
	if len(page.Samples) != 0 {
		t.Fatalf("outside range count = %d, want 0", len(page.Samples))
	}
}

func TestHistoryPagination(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	for i := 0; i < 5; i++ {
		replaySample(t, h, "dev-1", fmt.Sprintf("b-%d", i), fmt.Sprintf("e-%d", i),
			fmt.Sprintf("2026-01-0%dT00:00:00Z", i+1), map[string]float64{"v": float64(i + 1)})
	}

	page := fetchHistory(t, h, "dev-1", "limit=2")
	if len(page.Samples) != 2 || page.Samples[0].Seq != 1 || page.Samples[1].Seq != 2 {
		t.Fatalf("first page = %+v, want seq 1,2", page.Samples)
	}
	if page.NextCursor == nil {
		t.Fatal("first page cursor is nil")
	}

	page = fetchHistory(t, h, "dev-1", "limit=2&cursor="+*page.NextCursor)
	if len(page.Samples) != 2 || page.Samples[0].Seq != 3 || page.Samples[1].Seq != 4 {
		t.Fatalf("second page = %+v, want seq 3,4", page.Samples)
	}
	if page.NextCursor == nil {
		t.Fatal("second page cursor is nil")
	}

	page = fetchHistory(t, h, "dev-1", "limit=2&cursor="+*page.NextCursor)
	if len(page.Samples) != 1 || page.Samples[0].Seq != 5 {
		t.Fatalf("third page = %+v, want seq 5", page.Samples)
	}
	if page.NextCursor != nil {
		t.Fatalf("third page cursor = %q, want nil", *page.NextCursor)
	}
}

func TestHistoryPaginationStableUnderWrites(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	for i := 0; i < 5; i++ {
		replaySample(t, h, "dev-1", fmt.Sprintf("b-%d", i), fmt.Sprintf("e-%d", i),
			fmt.Sprintf("2026-01-0%dT00:00:00Z", i+1), map[string]float64{"v": float64(i + 1)})
	}

	// First page fixes the upper bound at the then-max seq (5).
	page := fetchHistory(t, h, "dev-1", "limit=2")
	if len(page.Samples) != 2 || page.Samples[1].Seq != 2 {
		t.Fatalf("first page = %+v, want seq 1,2", page.Samples)
	}
	cursor := *page.NextCursor

	// Concurrent writes happen between pages.
	rec := doJSON(t, h, http.MethodPost, "/v1/devices/dev-1/telemetry", `{"temperature":99}`)
	if rec.Code != http.StatusAccepted {
		t.Fatalf("telemetry: %d %s", rec.Code, rec.Body.String())
	}
	replaySample(t, h, "dev-1", "b-5", "e-5", "2026-01-06T00:00:00Z", map[string]float64{"v": 6})

	// Remaining pages stay within the fixed upper bound: no skips, no dupes.
	page = fetchHistory(t, h, "dev-1", "limit=2&cursor="+cursor)
	if len(page.Samples) != 2 || page.Samples[0].Seq != 3 || page.Samples[1].Seq != 4 {
		t.Fatalf("page after writes = %+v, want seq 3,4", page.Samples)
	}
	page = fetchHistory(t, h, "dev-1", "limit=2&cursor="+*page.NextCursor)
	if len(page.Samples) != 1 || page.Samples[0].Seq != 5 {
		t.Fatalf("last page = %+v, want seq 5", page.Samples)
	}
	if page.NextCursor != nil {
		t.Fatalf("cursor = %q, want nil", *page.NextCursor)
	}

	// A fresh first page sees the new writes.
	page = fetchHistory(t, h, "dev-1", "")
	if len(page.Samples) != 7 {
		t.Fatalf("fresh history count = %d, want 7", len(page.Samples))
	}
}

func TestHistoryValidation(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	replaySample(t, h, "dev-1", "b-1", "e-1", "2026-01-01T00:00:00Z", map[string]float64{"v": 1})

	cases := map[string]string{
		"bad from":          "from=not-a-time",
		"bad to":            "to=not-a-time",
		"inverted range":    "from=2026-01-02T00:00:00Z&to=2026-01-01T00:00:00Z",
		"limit zero":        "limit=0",
		"limit too large":   "limit=101",
		"limit non-numeric": "limit=abc",
		"empty cursor":      "cursor=",
		"tampered cursor":   "cursor=not-base64-json",
	}
	for name, query := range cases {
		t.Run(name, func(t *testing.T) {
			rec := doJSON(t, h, http.MethodGet, "/v1/devices/dev-1/history?"+query, "")
			if rec.Code != http.StatusBadRequest {
				t.Fatalf("status = %d, want %d: %s", rec.Code, http.StatusBadRequest, rec.Body.String())
			}
		})
	}
}

func TestHistoryCursorBoundToDeviceAndFilters(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	registerDevice(t, h, "dev-2")
	replaySample(t, h, "dev-1", "b-1", "e-1", "2026-01-01T00:00:00Z", map[string]float64{"v": 1})
	replaySample(t, h, "dev-2", "b-1", "e-1", "2026-01-01T00:00:00Z", map[string]float64{"v": 1})

	page := fetchHistory(t, h, "dev-1", "limit=1")
	if page.NextCursor == nil {
		t.Fatal("expected a cursor")
	}
	cursor := *page.NextCursor

	// Cursor cannot be used against another device.
	rec := doJSON(t, h, http.MethodGet, "/v1/devices/dev-2/history?limit=1&cursor="+cursor, "")
	if rec.Code != http.StatusBadRequest {
		t.Fatalf("cross-device cursor status = %d, want %d", rec.Code, http.StatusBadRequest)
	}

	// Cursor cannot be reused with changed filters.
	rec = doJSON(t, h, http.MethodGet, "/v1/devices/dev-1/history?limit=1&from=2026-01-01T00:00:00Z&cursor="+cursor, "")
	if rec.Code != http.StatusBadRequest {
		t.Fatalf("changed-filter cursor status = %d, want %d", rec.Code, http.StatusBadRequest)
	}
}

func TestHistoryUnknownDevice(t *testing.T) {
	h, _ := newTestHandler(t)
	rec := doJSON(t, h, http.MethodGet, "/v1/devices/missing/history", "")
	if rec.Code != http.StatusNotFound {
		t.Fatalf("status = %d, want %d", rec.Code, http.StatusNotFound)
	}
}

func TestHistoryDefaultLimit(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	for i := 0; i < 25; i++ {
		replaySample(t, h, "dev-1", fmt.Sprintf("b-%d", i), fmt.Sprintf("e-%d", i),
			"2026-01-01T00:00:00Z", map[string]float64{"v": float64(i)})
	}
	page := fetchHistory(t, h, "dev-1", "")
	if len(page.Samples) != 20 {
		t.Fatalf("default page size = %d, want 20", len(page.Samples))
	}
	if page.NextCursor == nil {
		t.Fatal("expected a cursor after 20 samples")
	}
}

